function setupChrome(){ const bs=$("#brandsub"); if(bs&&state.board) bs.textContent=`${BOARD_NAME[state.board]} ${SUBJECT} · flash cards`; setFooter(); }

/* ===== State ===== */
const state={board:null,course:null,tier:null,mode:'all',filter:'none',deck:[],i:0,revealed:false,answered:{},score:0,answeredCount:0,topic:null,custom:null,dir:1,streak:0};
