function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const US2UK={estrogen:'oestrogen',estrogens:'oestrogens',color:'colour',colored:'coloured',colors:'colours',tumor:'tumour',tumors:'tumours',vapor:'vapour',vapors:'vapours',behavior:'behaviour',diarrhea:'diarrhoea',hemoglobin:'haemoglobin',hemophilia:'haemophilia',fetus:'foetus',fetal:'foetal',esophagus:'oesophagus',fiber:'fibre',fibers:'fibres',fertilizer:'fertiliser',fertilizers:'fertilisers',fertilization:'fertilisation',specialized:'specialised',neutralize:'neutralise',neutralized:'neutralised',catalyze:'catalyse',catalyzed:'catalysed',catalyzes:'catalyses',analyze:'analyse',ionize:'ionise',ionized:'ionised'};
Object.assign(US2UK,{sulphur:'sulfur',sulphate:'sulfate',sulphates:'sulfates',sulphide:'sulfide',sulphite:'sulfite',sulphuric:'sulfuric',sulphurous:'sulfurous',aluminum:'aluminium',cesium:'caesium',meter:'metre',meters:'metres',liter:'litre',liters:'litres',center:'centre',centers:'centres',anemia:'anaemia',anemic:'anaemic',edema:'oedema',leukemia:'leukaemia',hemorrhage:'haemorrhage',hemolysis:'haemolysis',leukocyte:'leucocyte',leukocytes:'leucocytes',gonorrhea:'gonorrhoea',pediatric:'paediatric',anesthetic:'anaesthetic',feces:'faeces',fecal:'faecal',celiac:'coeliac',hypoglycemia:'hypoglycaemia',hyperglycemia:'hyperglycaemia',septicemia:'septicaemia',gray:'grey',aging:'ageing',mold:'mould',molds:'moulds',defense:'defence',organize:'organise',organized:'organised',organization:'organisation',recognize:'recognise',recognized:'recognised',utilize:'utilise',minimize:'minimise',maximize:'maximise',synthesize:'synthesise',synthesized:'synthesised',hydrolyze:'hydrolyse',hydrolyzed:'hydrolysed',electrolyze:'electrolyse',electrolyzed:'electrolysed',oxidize:'oxidise',oxidized:'oxidised',oxidization:'oxidisation',polymerize:'polymerise',polymerization:'polymerisation',crystallize:'crystallise',crystallized:'crystallised',crystallization:'crystallisation',vaporize:'vaporise',sterilize:'sterilise',sterilized:'sterilised',pasteurize:'pasteurise',pasteurized:'pasteurised',immunize:'immunise',immunization:'immunisation',stabilize:'stabilise',standardize:'standardise',characterize:'characterise',metabolize:'metabolise',metabolized:'metabolised',fertilize:'fertilise',fertilized:'fertilised',ionization:'ionisation',neutralization:'neutralisation',sensitize:'sensitise',carbonize:'carbonise',specialize:'specialise',specialization:'specialisation',hybridize:'hybridise',hybridization:'hybridisation',paralyze:'paralyse',paralyzed:'paralysed'});
const SUBS='₀₁₂₃₄₅₆₇₈₉', SUPS='⁰¹²³⁴⁵⁶⁷⁸⁹', SUPC={'¹':'1','²':'2','³':'3'};
function norm(s){
  let t=String(s).slice(0,300).trim();
  t=t.replace(/[₀-₉]/g,m=>String(SUBS.indexOf(m))).replace(/₊/g,'+').replace(/₋/g,'-');
  t=t.replace(/(.?)([⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻]+)/g,(m,p,run)=>{ const pl=[...run].map(c=>c==='⁺'?'+':c==='⁻'?'-':(SUPC[c]||String(SUPS.indexOf(c)))).join(''); return p+(/\d/.test(p)?'^':'')+pl; });
  t=t.toLowerCase().replace(/\s+/g,' ').trim().replace(/[.。]$/,'');
  t=t.replace(/℃/g,'°c').replace(/[º˚]/g,'°').replace(/\s*°\s*/g,'°').replace(/(\d)\s*degrees?\b/g,'$1°').replace(/\b(?:degrees?|deg)\s*(?:celsius|c)\b/g,'°c').replace(/\bcelsius\b/g,'°c').replace(/°{2,}/g,'°');
  t=t.replace(/[−–—‐‑]/g,'-').replace(/[μµ]/g,'u').replace(/∆/g,'δ').replace(/\bdelta\s*/g,'δ').replace(/δ\s+/g,'δ');
  t=t.replace(/[×·⋅∙]/g,'x').replace(/\*/g,'x');
  t=t.replace(/(?<=[a-z)])\^(\d+[+-])/g,'$1');
  t=t.replace(/(^|[^a-z\d.])(\d+\.?\d*)e([+-]?\d+)(?![\d.a-z])/g,(m,p,a,b)=>p+a+'x10^'+b.replace('+',''));
  t=t.replace(/(^|[^\d.^])10\s*(-\d+)(?!\d)/g,'$110^$2');
  while(/(\d),(\d{3})(?=\D|$)/.test(t)) t=t.replace(/(\d),(\d{3})(?=\D|$)/,'$1$2');
  t=t.replace(/(^|[^\d])\.(\d)/g,'$10.$2');
  t=t.replace(/\bper\s?cent\b/g,'%').replace(/\bpercent\b/g,'%');
  const NW={zero:0,one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12,thirteen:13,fourteen:14,fifteen:15,sixteen:16,seventeen:17,eighteen:18,nineteen:19,twenty:20,thirty:30,forty:40,fifty:50,sixty:60,seventy:70,eighty:80,ninety:90,hundred:100,thousand:1000};
  t=t.replace(/\b(twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)[- ](one|two|three|four|five|six|seven|eight|nine)\b/g,(m,a,b)=>String(NW[a]+NW[b]));
  t=t.replace(/\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand)\b/g,m=>String(NW[m]));
  t=t.split(' ').map(w=>US2UK[w]||w).join(' ');
  t=t.replace(/\s+per\s+/g,'/');
  t=t.replace(/([a-z])-(?=[a-z])/g,'$1 ');
  if(/\d/.test(t)) t=t.replace(/\s+/g,'');
  t=t.replace(/(^|[^\d.^])1x10\^/g,'$110^');
  t=t.replace(/(\d+\.\d*?)0+(?!\d)/g,'$1').replace(/(\d+)\.(?!\d)/g,'$1');
  return t;
}
const UNIT_WORDS={second:'s',metre:'m',gram:'g',kilogram:'kg',milligram:'mg',mole:'mol',litre:'l',millilitre:'ml',degree:'°',kilometre:'km',centimetre:'cm',millimetre:'mm',nanometre:'nm',micrometre:'um',kilojoule:'kj',joule:'j',hour:'h',minute:'min',hertz:'hz',pascal:'pa'};
const UNIT_SYM=new Set(['g','kg','mg','mol','mmol','ml','dm3','cm3','m3','cm2','m2','mm2','cm','mm','nm','um','km','°c','°','%','kj','j','min','hz','pa','kpa','atm','ppm','mol/dm3','g/dm3','g/cm3','g/mol','kj/mol','cm3/min','dm3/min']);
function unitCanon(u){ if(!u) return ''; return u.split('/').map(w=>{ let b=w; if(b.length>3&&b.endsWith('s')&&!/ss$/.test(b)) b=b.slice(0,-1); return UNIT_WORDS[b]||UNIT_WORDS[w]||w; }).join('/'); }
function unitOK(u){ if(!u) return true; const parts=u.split('/'); if(parts.length===1){ let b=u; if(b.length>3&&b.endsWith('s')&&!/ss$/.test(b)) b=b.slice(0,-1); return !!UNIT_WORDS[b]||UNIT_SYM.has(u); } return UNIT_SYM.has(u)||parts.every(p=>unitOK(p)); }
function numVal(t){ let m;
  if((m=t.match(/^([-+]?(?:\d+\.?\d*|\.\d+))x10\^([-+]?\d+)$/))) return parseFloat(m[1])*Math.pow(10,+m[2]);
  if((m=t.match(/^10\^([-+]?\d+)$/))) return Math.pow(10,+m[1]);
  if(/^[-+]?(?:\d+\.?\d*|\.\d+)$/.test(t)) return parseFloat(t);
  return null; }
function splitNU(t){ const m=t.match(/^([-+]?(?:\d+\.?\d*|\.\d+)(?:x10\^[-+]?\d+)?|10\^[-+]?\d+)(?:([a-z°%][a-z°%\/\^\-\d]*))?$/); if(!m) return null; const n=numVal(m[1]); if(n===null) return null; if(m[2]&&!unitOK(m[2])) return null; return {n:n,u:unitCanon(m[2]||'')}; }
function isFormula(r){ r=String(r).trim(); return /^[A-Za-z0-9()\[\]]+[+\-⁺⁻₊₋²³]*$/.test(r)&&/[A-Z].*[A-Z]|\d|[+\-⁺⁻]$|^[A-Z][a-z]?$/.test(r); }
function pluralEq(a,v){ if(a.length<3||v.length<3) return false; if(a+'s'===v||v+'s'===a||a+'es'===v||v+'es'===a) return true; if(a.endsWith('y')&&a.slice(0,-1)+'ies'===v) return true; if(v.endsWith('y')&&v.slice(0,-1)+'ies'===a) return true; return false; }
function eqAns(a,v,ra,rv){
  if(a===v) return true;
  const A=splitNU(a), V=splitNU(v);
  if(A&&V){ const close=A.n===V.n||Math.abs(A.n-V.n)<=1e-9*Math.max(Math.abs(A.n),Math.abs(V.n)); if(close&&(!A.u||!V.u||A.u===V.u)) return true; }
  if(!/\d/.test(a)&&!/\d/.test(v)&&a.length>=3&&a.replace(/ /g,'')===v.replace(/ /g,'')) return true;
  if(!/\d/.test(a)&&!/\d/.test(v)&&!isFormula(ra)&&!isFormula(rv)&&pluralEq(a,v)) return true;
  return false;
}
function accepts(ans,val){ const list=Array.isArray(ans)?ans:[ans]; const v=norm(val); if(!v) return false; return list.some(a=>eqAns(norm(a),v,a,val)); }
function canonical(ans){return Array.isArray(ans)?ans[0]:ans;}

function esc(s){return String(s).replace(/[&<>"'`]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;','`':'&#96;'}[c]));}
/* Level gate + card-set mode + the active filter. */
function fits(card){
  if((card.board||'aqa')!==state.board)return false; // exam board (cards without a board field are AQA)
  if(card.user){ // the student's own cards: always available in their board, any tier/course/mode
    if(state.filter==='core'&&!card.core)return false;
    if(state.filter==='rp'&&!card.rp)return false;
    if(state.filter==='maths'&&!card.maths)return false;
    if(state.filter==='marked'&&!marked.has(card.id))return false;
    return true;
  }
  if(!card.tiers.includes(state.tier)||!card.courses.includes(state.course))return false;
  if(state.mode==='hy'&&!card.hy)return false;
  if(state.filter==='core'&&!card.core)return false;
    if(state.filter==='rp'&&!card.rp)return false;
  if(state.filter==='maths'&&!card.maths)return false;
  if(state.filter==='marked'&&!marked.has(card.id))return false;
  return true;
}

/* ===== Persistence (__LS, best-effort) ===== */
function loadPersisted(){
  try{const m=JSON.parse(__LS.getItem('g2m-marked')||'[]'); if(Array.isArray(m))m.forEach(id=>{if(typeof id==='string')marked.add(id);});}catch(e){}
  try{Object.assign(mastery,g2mCleanMastery(JSON.parse(__LS.getItem('g2m-mastery')||'{}')));}catch(e){}
  try{const sn=JSON.parse(__LS.getItem('g2m-seen')||'{}'); if(sn&&typeof sn==='object'&&!Array.isArray(sn))for(const k of Object.keys(sn)){if(k!=='__proto__'&&Array.isArray(sn[k]))seenIds[k]=new Set(sn[k].filter(x=>typeof x==='string'));}}catch(e){}
}
function saveMarked(){try{__LS.setItem('g2m-marked',JSON.stringify([...marked]));}catch(e){}}
function saveMastery(){
  try{__LS.setItem('g2m-mastery',JSON.stringify(mastery));}catch(e){}
  try{const o={};for(const k in seenIds)o[k]=[...seenIds[k]];__LS.setItem('g2m-seen',JSON.stringify(o));}catch(e){}
}
function markSeen(card){
  if(!card||!card.topic)return;
  (seenIds[card.topic]=seenIds[card.topic]||new Set()).add(card.id);
  saveMastery();
}
/* Coverage % for a topic = seen ÷ total cards available to this student (all-cards mode). */
function coverageFor(topicKey){
  const set=seenIds[topicKey]; let total=0, seen=0;
  for(const c of CARDS){ if(c.topic!==topicKey||!c.tiers.includes(state.tier)||!c.courses.includes(state.course))continue; total++; if(set&&set.has(c.id))seen++; }
  return total?Math.round(seen/total*100):0;
}
function bestScoreFor(topicKey){ const b=mastery[topicKey]&&mastery[topicKey].best; return (typeof b==='number'&&isFinite(b))?Math.max(0,Math.min(100,Math.round(b))):0; }

/* Wipe saved progress (marked, mastery, coverage) + in-memory decks. Keeps level/theme. */
function resetAllProgress(){
  marked.clear();
  for(const k in mastery)delete mastery[k];
  for(const k in seenIds)delete seenIds[k];
  for(const k in sessions)delete sessions[k];
  Object.keys(blurtStore).forEach(k=>{delete blurtStore[k];});
  try{__LS.removeItem('g2m-marked');__LS.removeItem('g2m-mastery');__LS.removeItem('g2m-seen');}catch(e){}
}

g2mMigrate();
loadPersisted();

/* ===== other tabs (same app): keep this tab's memory in step with storage ===== */
window.addEventListener('storage',function(e){
  try{
    const pre='g2m-'+__G2M_SUBJ+'-';
    if(e.key!==null&&e.key.indexOf(pre)!==0)return;
    const n=e.key===null?'all':e.key.slice(pre.length);
    if(n==='all'||n==='marked'||n==='mastery'||n==='seen'){ marked.clear(); for(const k in mastery)delete mastery[k]; for(const k in seenIds)delete seenIds[k]; loadPersisted(); }
    if(n==='all'||n==='usercards'){ for(let i=CARDS.length-1;i>=0;i--)if(CARDS[i].user)CARDS.splice(i,1); g2mMergeUserCards(); }
    if(n==='all'||n==='opened'){ try{ const o=JSON.parse(__LS.getItem('g2m-opened')||'{}'); for(const k in openedAt)delete openedAt[k]; if(o&&typeof o==='object'&&!Array.isArray(o))for(const k of Object.keys(o))if(k!=='__proto__'&&typeof o[k]==='number'&&isFinite(o[k]))openedAt[k]=o[k]; }catch(_){} }
    if(!$("#screen-topics").hidden)renderTopicList();
  }catch(_){}
});

/* ===== Theme toggle ===== */
(function(){
  function isDarkNow(){
    const cur=document.documentElement.getAttribute('data-theme');
    return cur?cur==='dark':matchMedia('(prefers-color-scheme:dark)').matches;
  }
  // Label shows the mode the button switches TO.
  function syncThemeBtn(){ $("#themeBtn").textContent = isDarkNow() ? '☀️ Light' : '🌙 Dark'; }
  let t=null; try{t='light';}catch(e){}
  if(t==='light'||t==='dark')document.documentElement.setAttribute('data-theme',t);
  syncThemeBtn();
  $("#themeBtn").addEventListener('click',()=>{
    const next=isDarkNow()?'light':'dark';
    document.documentElement.setAttribute('data-theme',next);
    try{__LS.setItem('g2m-theme',next);}catch(e){}
    syncThemeBtn();
  });
  // Keep the label right if the OS theme changes while on 'system'.
  try{ matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{ if(!document.documentElement.getAttribute('data-theme'))syncThemeBtn(); }); }catch(e){}
})();

/* ===== Reset all progress (two-step confirm) ===== */
(function(){
  const link=$("#resetBtn"), confirm=$("#resetConfirm"), done=$("#resetDone"), yes=$("#resetYes"), no=$("#resetNo");
  function showState(which){ link.hidden=which!=='link'; confirm.hidden=which!=='confirm'; done.hidden=which!=='done'; }
  link.addEventListener('click',()=>showState('confirm'));
  no.addEventListener('click',()=>showState('link'));
  yes.addEventListener('click',()=>{
    resetAllProgress();
    showState('done');
    // Refresh whatever screen is open so cleared data shows immediately.
    if(!$("#screen-topics").hidden) renderTopicList();
    setTimeout(()=>showState('link'),2500);
  });
})();

/* ===== Setup gate ===== */
function refreshStart(){
  const btn=$("#startBtn"); try{ updateTierHelp(); }catch(e){}
  if(state.board&&state.course&&state.tier){btn.disabled=false;btn.textContent="Start revising ›";}
  else{btn.disabled=true;btn.textContent="Choose all three to continue";}
}
function clearSessions(){for(const k in sessions)delete sessions[k];}
$("#board-opts").addEventListener('click',e=>{
  const b=e.target.closest('[data-board]');if(!b||b.disabled)return;
  if(state.board&&state.board!==b.dataset.board)clearSessions(); // board changed → drop resume data
  state.board=b.dataset.board;
  document.body.setAttribute('data-board-theme',state.board);
  setupChrome();
  [...$("#board-opts").children].forEach(x=>x.setAttribute('aria-pressed',x===b));
  refreshStart();
});
$("#course-opts").addEventListener('click',e=>{
  const b=e.target.closest('[data-course]');if(!b)return;
  if(state.course&&state.course!==b.dataset.course)clearSessions(); // level changed → drop resume data
  state.course=b.dataset.course;
  [...$("#course-opts").children].forEach(x=>x.setAttribute('aria-pressed',x===b));
  refreshStart();
});
$("#tier-opts").addEventListener('click',e=>{
  const b=e.target.closest('[data-tier]');if(!b)return;
  if(state.tier&&state.tier!==b.dataset.tier)clearSessions(); // level changed → drop resume data
  state.tier=b.dataset.tier;
  [...$("#tier-opts").children].forEach(x=>x.setAttribute('aria-pressed',x===b));
  refreshStart();
});
$("#startBtn").addEventListener('click',()=>{try{__LS.setItem('g2m-setup',JSON.stringify({b:state.board,c:state.course,t:state.tier}));}catch(e){}; openTopics();});
$("#editSetup").addEventListener('click',()=>show("screen-setup"));

/* restore prior setup + card-set mode */
(function(){
  try{const m=__LS.getItem('g2m-mode'); if(m==='hy'||m==='all')state.mode=m;}catch(e){}
  let s=null;try{s=JSON.parse(__LS.getItem('g2m-setup')||'null');}catch(e){}
  if(s&&typeof s==='object'&&typeof s.b==='string'&&Object.prototype.hasOwnProperty.call(BOARD_NAME,s.b)&&(s.c==='combined'||s.c==='triple')&&(s.t==='F'||s.t==='H')){state.board=s.b;state.course=s.c;state.tier=s.t;document.body.setAttribute('data-board-theme',s.b);
    setupChrome();
    const bb=$(`[data-board="${s.b}"]`),cb=$(`[data-course="${s.c}"]`),tb=$(`[data-tier="${s.t}"]`);
    if(bb){[...$("#board-opts").children].forEach(x=>x.setAttribute('aria-pressed',x===bb));}
    if(cb){[...$("#course-opts").children].forEach(x=>x.setAttribute('aria-pressed',x===cb));}
    if(tb){[...$("#tier-opts").children].forEach(x=>x.setAttribute('aria-pressed',x===tb));}
    refreshStart();
  }
})();

/* ===== Topic picker ===== */
/* Ring colour by coverage: <30 red, 30–60 amber, >60 green (deepening as it climbs). */
function masteryColour(cov){
  if(cov<30) return 'var(--bad)';
  if(cov<60) return 'var(--amber)';
  if(cov<85) return 'var(--good)';
  return '#0a6b45'; // strongest green for near-complete
}
function masteryHTML(topicKey){
  const cov=coverageFor(topicKey), best=bestScoreFor(topicKey);
  if(cov===0&&best===0) return ''; // nothing to show until they've studied it
  const col=masteryColour(cov);
  const ring=`<span class="m-ring" style="--p:${cov};--mc:${col}" title="${cov}% of this topic seen"><span>${cov}</span></span>`;
  const meta=`<span class="m-meta">${best>0?`<span class="m-score">${best}% best</span>`:''}<span class="m-seen">${cov}% seen</span></span>`;
  return `<span class="mastery">${meta}${ring}</span>`;
}
let openedAt=(function(){try{const o=JSON.parse(__LS.getItem('g2m-opened')||'{}');const r={}; if(o&&typeof o==='object'&&!Array.isArray(o))for(const k of Object.keys(o))if(k!=='__proto__'&&typeof o[k]==='number'&&isFinite(o[k]))r[k]=o[k]; return r;}catch(e){return {};}})();
function recordOpen(key){openedAt[key]=Date.now();try{__LS.setItem('g2m-opened',JSON.stringify(openedAt));}catch(e){}}
function relTime(ts){const m=Math.floor((Date.now()-ts)/60000);if(m<1)return 'just now';if(m<60)return m+'m ago';const h=Math.floor(m/60);if(h<24)return h+'h ago';const d=Math.floor(h/24);if(d===1)return 'yesterday';if(d<7)return d+'d ago';const w=Math.floor(d/7);if(w<5)return w+(w===1?' week':' weeks')+' ago';const mo=Math.floor(d/30);if(mo<12)return mo+(mo===1?' month':' months')+' ago';return 'over a year ago';}
function makeTopicBtn_old(t){
  const n=CARDS.filter(c=>c.topic===t.key&&fits(c)).length;
  const s=sessions[sessKey(t.key)];
  const inProgress = s && (s.i>0 || s.answeredCount>0);
  const b=document.createElement('button');
  b.className="topic";b.type="button";if(!n)b.disabled=true;
  const right = !n
    ? `<span class="count">0 cards</span>`
    : inProgress
      ? `<span class="count">Resume · ${s.i+1}/${n}</span>`
      : `<span class="count">${n} card${n===1?'':'s'}</span>`;
  b.innerHTML=`<span class="meta"><b>${esc(topicTitle(t))}</b><span>${esc(t.section)} · ${esc(t.spec)}</span>${openedAt[t.key]?`<span class="t-opened">Last opened ${relTime(openedAt[t.key])}</span>`:''}</span>${masteryHTML(t.key)}${right}`;
  if(n)b.addEventListener('click',()=>{ recordOpen(t.key); if(studyMode==='browse') openBrowse(t.key); else startTopic(t.key); });
  return b;
}
function renderTopicList(){
  const list=$("#topicList");list.innerHTML="";
  const _q=searchQ(); const topics=currentTopics().filter(t=>topicMatches(t,_q));
  // Group by each topic's section, in the order sections first appear.
  const sections=[];
  topics.forEach(t=>{ if(!sections.includes(t.section))sections.push(t.section); });
  sections.forEach(sec=>{
    const h=document.createElement('div');
    h.className="paper-head";
    h.textContent=sec;
    list.appendChild(h);
    topics.filter(t=>t.section===sec).forEach(t=>list.appendChild(makeTopicBtn(t)));
  });
  if(_q&&!topics.length){ const p=document.createElement('p'); p.className='muted'; p.style.margin='8px 2px 16px'; p.textContent='No topics match “'+_q+'”.'+(_q.length>=3?' Card matches are listed above.':''); list.appendChild(p); }
  renderSearchResults(); updateQuickBtn();
}
function openTopics(){
  const sub=`${BOARD_NAME[state.board]} Biology · ${COURSE_NAME[state.course]} · ${TIER_NAME[state.tier]} tier`;
  $("#brandsub").textContent=sub;
  setFooter();
  $("#levelChip").textContent=`${BOARD_NAME[state.board]} · ${COURSE_NAME[state.course]} · ${TIER_NAME[state.tier]} tier`;
  [...$("#modeSwitch").children].forEach(b=>b.setAttribute('aria-pressed', b.dataset.mode===state.mode));
  [...$("#filterBar").querySelectorAll('.fchip')].forEach(b=>b.setAttribute('aria-pressed', b.dataset.filter===state.filter));
  { const rc=$("#filterBar").querySelector('[data-filter="rp"]'); if(rc){ rc.textContent=RP_LABEL[state.board]||'Required practicals'; rc.title='Only cards linked to the '+BOARD_NAME[state.board]+' '+rc.textContent; } updateQuickBtn(); }
  [...$("#studyToggle").children].forEach(b=>b.setAttribute('aria-pressed', b.dataset.study===studyMode));
  renderTopicList();
  show("screen-topics");
}
