function browseItem(c){
  const hy=(c.hy?` · <span class="bhy">✦ high-yield</span>`:'')+(c.core?` · <span class="bhy">◆ core</span>`:'');
  const head=`<div class="btype">${TYPE_LABEL[c.type]}${c.user?' <span class="user-badge">Your card</span>':''}${hy}${c.user?`<button class="b-del" data-del="${esc(c.id)}" aria-label="Delete this card">Delete</button><button class="b-del b-edit" data-edit="${esc(c.id)}" aria-label="Edit this card">Edit</button>`:''}</div>`;
  let bodyHtml='';
  if(c.type==='flip'){
    bodyHtml=`<div class="bq">${esc(c.front)}</div><div class="ba">${esc(c.back)}</div>`;
  } else if(c.type==='gap'){
    let idx=0;
    const filled=c.text.split("___").map((seg,k,arr)=>esc(seg)+(k<arr.length-1?`<b class="bfill">${esc(canonical(c.answers[idx++]))}</b>`:'')).join("");
    bodyHtml=`<div class="bq">${filled}</div>`;
  } else if(c.type==='mcq'){
    const opts=c.options.map((o,k)=>`<div class="bopt${k===c.correct?' bcorrect':''}">${k===c.correct?'✓ ':''}${esc(o)}</div>`).join("");
    bodyHtml=`<div class="bq">${esc(c.question)}</div><div class="bopts">${opts}</div><div class="ba">${esc(c.why)}</div>`;
  } else if(c.type==='match'){
    const rows=c.pairs.map(p=>`<div class="bpair"><span>${esc(p[0])}</span><span class="barrow">→</span><span>${esc(p[1])}</span></div>`).join("");
    bodyHtml=`<div class="bq">${esc(c.prompt)}</div><div class="bpairs">${rows}</div>`;
  }
  return `<div class="bcard">${head}${bodyHtml}</div>`;
}
function openBrowse(key){
  state.browseKey=key;
  const deck=CARDS.filter(c=>c.topic===key&&fits(c)); // spec order (array order), respects mode + filter
  const t=currentTopics().find(x=>x.key===key)||{};
  $("#browseTitle").textContent=(t.title?topicTitle(t):'Browse');
  $("#browseCount").textContent=`${deck.length} card${deck.length===1?'':'s'}`;
  $("#browseList").innerHTML=deck.length?deck.map(browseItem).join(""):`<p class="muted">No cards match “${esc(filterLabel())}”${state.mode==='hy'?' in High-yield mode':''}.</p>`;
  show("screen-browse");
  const sc=document.scrollingElement||document.documentElement; if(sc)sc.scrollTop=0;
}
