const USERCARDS_KEY='g2m-usercards';
function validUserCard(c){return g2mValidCard(c);}
function loadUserCards(){try{const a=JSON.parse(__LS.getItem(USERCARDS_KEY)||'[]');return Array.isArray(a)?a.filter(validUserCard):[];}catch(e){return [];}}
const _deletedUC=new Set();
/* re-read before write: cards added in another tab of this app are kept (unless deleted here) */
function persistUserCards(){try{const mem=CARDS.filter(c=>c.user),have=new Set(mem.map(c=>c.id));const disk=loadUserCards().filter(c=>!have.has(c.id)&&!_deletedUC.has(c.id));__LS.setItem(USERCARDS_KEY,JSON.stringify(mem.concat(disk)));return true;}catch(e){return false;}}
function g2mMergeUserCards(){for(const c of loadUserCards()){if(!CARDS.some(x=>x.id===c.id)){c.user=true;if(!Array.isArray(c.tiers))c.tiers=["F","H"];if(!Array.isArray(c.courses))c.courses=["combined","triple"];if(typeof c.chunk!=='number')c.chunk=999;CARDS.push(c);}}}
