function syncGapAnswers(){const n=($("#acGapText").value.match(/___/g)||[]).length;const wrap=$("#acGapAnswers");const prev=[...wrap.querySelectorAll('.ac-ans')].map(i=>i.value);wrap.innerHTML=n?`<label class="ac-lbl">Answer${n>1?'s':''} <span class="ac-hint">— one per blank</span></label>`+Array.from({length:n},(_,i)=>`<input class="ac-input ac-ans" data-ai="${i}" placeholder="Answer for blank ${i+1}" value="${esc(prev[i]||'')}">`).join(''):`<p class="ac-hint">Add ___ to your sentence to create a blank.</p>`;}
function resetAcForm(){acStyle=null;[...$("#acStyles").children].forEach(b=>b.setAttribute('aria-pressed','false'));for(const k in AC_FIELD)$("#"+AC_FIELD[k]).hidden=true;$("#acFlipFront").value='';$("#acFlipBack").value='';$("#acGapText").value='';$("#acGapAnswers").innerHTML='';$("#acMcqQ").value='';$("#acMcqWhy").value='';buildMcqOpts();$("#acMatchPrompt").value='';buildMatchPairs();updateAcSave();}
function openAddCard(presetTopic){const sel=$("#acTopic");sel.innerHTML=currentTopics().map(t=>`<option value="${esc(t.key)}">${esc(topicTitle(t))}</option>`).join("");if(presetTopic)sel.value=presetTopic;$("#acMsg").hidden=true;resetAcForm();show('screen-addcard');const sc=document.scrollingElement||document.documentElement;if(sc)sc.scrollTop=0;}
function acValid(){if(!acStyle)return false;
  if(acStyle==='flip')return !!($("#acFlipFront").value.trim()&&$("#acFlipBack").value.trim());
  if(acStyle==='gap'){const n=($("#acGapText").value.match(/___/g)||[]).length;if(!n)return false;const a=[...$("#acGapAnswers").querySelectorAll('.ac-ans')];return a.length===n&&a.every(x=>x.value.trim());}
  if(acStyle==='mcq'){const q=$("#acMcqQ").value.trim();const opts=[...$("#acMcqOpts").querySelectorAll('.ac-opt')].map(o=>o.value.trim());const chk=$("#acMcqOpts").querySelector('input[name=acCorrect]:checked');return !!(q&&opts.filter(Boolean).length>=2&&chk&&opts[+chk.value]);}
  if(acStyle==='match'){const p=$("#acMatchPrompt").value.trim();const pairs=[...$("#acMatchPairs").querySelectorAll('.ac-pairrow')].map(r=>[r.querySelector('.ac-pl').value.trim(),r.querySelector('.ac-pr').value.trim()]).filter(x=>x[0]&&x[1]);const lefts=pairs.map(x=>x[0]);return !!(p&&pairs.length>=2&&new Set(lefts).size===lefts.length);}
  return false;}
function updateAcSave(){const b=$("#acSave");const ok=acValid();b.disabled=!ok;b.textContent=acStyle?(ok?(window.__acEdit?'Save changes':'Add this card'):'Fill in the card'):'Choose a style first';}
$("#acStyles").addEventListener('click',e=>{const b=e.target.closest('[data-style]');if(!b)return;acStyle=b.dataset.style;[...$("#acStyles").children].forEach(x=>x.setAttribute('aria-pressed',x===b));for(const k in AC_FIELD)$("#"+AC_FIELD[k]).hidden=(k!==acStyle);if(acStyle==='gap')syncGapAnswers();updateAcSave();});
