function deleteUserCard(id){const i=CARDS.findIndex(c=>c.id===id&&c.user);if(i<0)return;_deletedUC.add(id);CARDS.splice(i,1);persistUserCards();if(state.browseKey)openBrowse(state.browseKey);}
$("#browseList").addEventListener('click',e=>{const d=e.target.closest('[data-del]');if(!d)return;if(d.dataset.confirm){deleteUserCard(d.dataset.del);}else{d.dataset.confirm='1';d.textContent='Delete?';setTimeout(()=>{if(d&&d.dataset){d.removeAttribute('data-confirm');d.textContent='Delete';}},2500);}});

/* ===== Custom session builder ===== */
const customSel=new Set();   // selected topic keys
let customCount=20;          // chosen number of cards (slider value)
let sliderAtMax=false;        // true while the user is sitting at the top of the range
function customPoolSize(){
  return CARDS.filter(c=>customSel.has(c.topic)&&fits(c)).length;
}
/* Update the slider's range to the available pool and keep the value sensible. */
function syncSlider(){
  const pool=customPoolSize();
  const slider=$("#countSlider");
  if(pool===0){
    slider.disabled=true; slider.min=1; slider.max=1; slider.value=1;
    $("#sliderMax").textContent='—'; $("#countRead").textContent='—';
    return;
  }
  slider.disabled=false; slider.min=1; slider.max=pool;
  // If they were pinned to the max, grow with the pool; otherwise clamp their number.
  let v = sliderAtMax ? pool : Math.min(customCount, pool);
  if(v<1)v=1;
  customCount=v; slider.value=v;
  sliderAtMax = (v===pool);
  $("#sliderMax").textContent=pool; $("#sliderMin").textContent=1;
  $("#countRead").textContent = v+(v===pool&&pool>1?' (all)':'');
}
function refreshCustom(){
  const pool=customPoolSize();
  $("#customTopicCount").textContent=customSel.size?`· ${customSel.size} selected`:'';
  syncSlider();
  $("#customAvail").textContent = pool===0
    ? 'No cards match yet — pick at least one topic.'
    : `${pool} card${pool===1?'':'s'} available in your chosen topic${customSel.size===1?'':'s'}.`;
  const start=$("#customStart");
  if(pool===0){start.disabled=true;start.textContent='Pick some topics to start';}
  else{start.disabled=false;start.textContent=`Start ${customCount} random card${customCount===1?'':'s'} ›`;}
}
function renderCustomTopics(){
  {const _k=new Set(currentTopics().map(t=>t.key));[...customSel].forEach(x=>{if(!_k.has(x))customSel.delete(x);});}
  const list=$("#customTopicList");list.innerHTML="";
  currentTopics().forEach(t=>{
    const n=CARDS.filter(c=>c.topic===t.key&&fits(c)).length;
    const b=document.createElement('button');
    b.className="ctopic";b.type="button";b.dataset.topic=t.key;
    if(!n){b.disabled=true;customSel.delete(t.key);}
    b.setAttribute('aria-pressed', customSel.has(t.key));
    b.innerHTML=`<span class="tick">${customSel.has(t.key)?'✓':''}</span><span class="ct-name">${esc(topicTitle(t))}</span><span class="ct-n">${n}</span>`;
    if(n)b.addEventListener('click',()=>{
      if(customSel.has(t.key))customSel.delete(t.key); else customSel.add(t.key);
      b.setAttribute('aria-pressed',customSel.has(t.key));
      b.querySelector('.tick').textContent=customSel.has(t.key)?'✓':'';
      refreshCustom();
    });
    list.appendChild(b);
  });
}
function openCustom(){
  $("#customChip").textContent=`${BOARD_NAME[state.board]} · ${COURSE_NAME[state.course]} · ${TIER_NAME[state.tier]} tier${state.mode==='hy'?' · High-yield':''}`;
  renderCustomTopics();
  refreshCustom();
  show("screen-custom");
}
$("#customBack").addEventListener('click',openTopics);
$("#customAll").addEventListener('click',()=>{
  currentTopics().forEach(t=>{ if(CARDS.filter(c=>c.topic===t.key&&fits(c)).length) customSel.add(t.key); });
  renderCustomTopics();refreshCustom();
});
$("#customNone").addEventListener('click',()=>{ customSel.clear();renderCustomTopics();refreshCustom(); });
$("#countSlider").addEventListener('input',e=>{
  const pool=customPoolSize();
  customCount=parseInt(e.target.value,10)||1;
  sliderAtMax=(customCount>=pool);
  $("#countRead").textContent = customCount+(customCount>=pool&&pool>1?' (all)':'');
  const start=$("#customStart");
  if(pool>0){start.textContent=`Start ${customCount} random card${customCount===1?'':'s'} ›`;}
});
$("#customStart").addEventListener('click',()=>{
  const pool=shuffle(CARDS.filter(c=>customSel.has(c.topic)&&fits(c)));
  const n = Math.min(customCount, pool.length);
  state.custom={topics:[...customSel], count:n};
  state.topic=null;
  startDeck(pool.slice(0,n), 'custom');
});

/* ===== Study session ===== */
/* Topic sessions are keyed by topic + mode + filter, so each view resumes separately. */
function sessKey(topic,mode){return (mode||state.mode)+'|'+state.filter+'|'+topic;}
function saveSession(){
  if(!state.topic)return; // custom sessions aren't resumable from the picker
  sessions[sessKey(state.topic)]={
    deck:state.deck,i:state.i,revealed:state.revealed,
    answered:state.answered,score:state.score,answeredCount:state.answeredCount
  };
}
/* Fresh deck of the given cards (custom session, or a retry). */
function startDeck(cards, label){
  if(!cards||!cards.length){ try{announce('No cards match the current filter.');}catch(e){} try{openTopics();}catch(e){} return; }
  Object.keys(blurtStore).forEach(k=>{delete blurtStore[k];});
  state.deck=cards.slice();
  state.i=0;state.revealed=false;state.answered={};state.score=0;state.answeredCount=0;
  state.dir=1; state.streak=0; lastStreakShown=0;
  render();show("screen-study");
}
/* Enter a topic: resume saved progress if any, otherwise start fresh. */
function startTopic(key,fresh){
  state.topic=key; state.custom=null;
  state.dir=1; state.streak=0; lastStreakShown=0;
  const saved=sessions[sessKey(key)];
  if(saved&&!fresh){
    state.deck=saved.deck;state.i=saved.i;state.revealed=saved.revealed;
    state.answered=saved.answered;state.score=saved.score;state.answeredCount=saved.answeredCount;
  } else {
    const _pool=shuffle(CARDS.filter(c=>c.topic===key&&fits(c)));
    if(!_pool.length){ try{announce('No cards match the current filter.');}catch(e){} try{openTopics();}catch(e){} return; }
    Object.keys(blurtStore).forEach(k=>{delete blurtStore[k];});
    state.deck=_pool;
    state.i=0;state.revealed=false;state.answered={};state.score=0;state.answeredCount=0;
    saveSession();
  }
  render();show("screen-study");
}
$("#againBtn").addEventListener('click',()=>{
  if(state.custom&&state.custom.weak&&typeof startWeak==='function'){ startWeak(); return; }
  if(state.custom&&state.custom.quick){ startQuick(); return; }
  if(state.custom&&state.custom.search){ const m=CARDS.filter(c=>state.custom.ids.includes(c.id)&&fits(c)); startDeck(shuffle(m),'search'); return; }
  if(state.custom){
    // redraw a fresh random set from the same chosen topics
    const pool=shuffle(CARDS.filter(c=>state.custom.topics.includes(c.topic)&&fits(c)));
    const n=state.custom.count==='all'?pool.length:Math.min(state.custom.count,pool.length);
    startDeck(pool.slice(0,n),'custom');
  } else {
    startTopic(state.topic,true);
  }
});

function current(){return state.deck[state.i];}
function updateProgress(){
  try{ const b=$("#progFill").parentElement; b.setAttribute('role','progressbar'); b.setAttribute('aria-label','Card progress'); b.setAttribute('aria-valuemin','1'); b.setAttribute('aria-valuemax',String(state.deck.length)); b.setAttribute('aria-valuenow',String(state.i+1)); }catch(e){}
  const n=state.deck.length;
  $("#countTxt").textContent=`${state.i+1} / ${n}`;
  $("#progFill").style.width=((state.i)/(n))*100+"%";
}
$("#prevBtn").addEventListener('click',()=>{if(state.i>0){state.i--;state.revealed=false;state.dir=-1;render();}});
$("#nextBtn").addEventListener('click',nextCard);
function nextCard(){
  if(state.i<state.deck.length-1){state.i++;state.revealed=false;state.dir=1;render();}
  else finish();
}
/* Flip live (animated) instead of re-rendering, so the card physically turns. */
function doFlip_old(){
  const c=current();
  const ta=document.getElementById('blurt');
  if(ta&&c){ // save the student's blurt and show it above the answer
    blurtStore[c.id]=ta.value;
    const rc=document.getElementById('blurtRecall');
    if(rc){ if(ta.value.trim()){ rc.innerHTML='<span class="blurt-lbl">You wrote</span>'+esc(ta.value); rc.hidden=false; } else { rc.hidden=true; } }
  }
  state.revealed=!state.revealed;
  const el=$("#flip3d");
  if(el){ el.classList.toggle('flipped',state.revealed); saveSession(); $("#actionBtn").textContent=state.revealed?"Flip back":"Flip card"; }
  else render();
}
$("#actionBtn").addEventListener('click',()=>{
  const c=current();
  if(c.type==="flip"){doFlip();}
  else if(c.type==="gap"){ if(!state.answered[c.id]) checkGap(c); else nextCard(); }
  else if(c.type==="match"){ if(!state.answered[c.id]) checkMatch(c); else nextCard(); }
  else if(c.type==="mcq"){ nextCard(); } // mcq auto-checks on choice; button = next
});

/* ---- renderers ---- */
function render0(){
  saveSession(); // in-memory progress (topic sessions)
  const c=current(); const host=$("#cardHost"); updateProgress();
  markSeen(c); // persisted coverage for mastery
  updateCardTools(c); // star + speaker state for this card
  stopSpeaking(); // don't carry audio across cards
  const back=state.dir===-1?' is-back':''; // entrance direction for the slide-in animation
  const hyTag = state.mode==='hy' ? `<span class="hy-badge">✦ High-yield</span>` : '';
  const tag=`<div class="type-tag"><span class="dot"></span>${TYPE_LABEL[c.type]}${c.user?' <span class="user-badge">Your card</span>':''}${hyTag}</div>`;
  const act=$("#actionBtn");
  $("#prevBtn").disabled=state.i===0;
  updateStreak();

  if(c.type==="flip"){
    const bl=blurtStore[c.id]||'';
    host.innerHTML=`<div class="cardbox${back}" style="padding:0;animation:none;flex:1;min-height:200px">
      <div class="flip3d ${state.revealed?'flipped':''}" id="flip3d" role="group" aria-label="Flash card">
        <div class="flip3d-inner">
          <div class="flip-face front">
            <span class="flip-badge"><span class="dot"></span>${TYPE_LABEL[c.type]} · Part ${c.chunk}${hyTag}</span>
            <div class="flip-q">${esc(c.front)}</div>
            <textarea class="blurt" id="blurt" placeholder="Blurt it out — write what you remember, then flip to check." aria-label="Write your answer">${esc(bl)}</textarea>
          </div>
          <div class="flip-face is-back">
            <span class="flip-badge ans"><span class="dot"></span>Answer</span>
            ${bl.trim()?`<div class="blurt-recall" id="blurtRecall"><span class="blurt-lbl">You wrote</span>${esc(bl)}</div>`:`<div class="blurt-recall" id="blurtRecall" hidden></div>`}
            <div class="flip-a">${fmtAns(c.back)}</div>
          </div>
        </div>
      </div>
    </div>`;
    act.textContent=state.revealed?"Flip back":"Flip card";
    act.className="ctl primary";act.disabled=false;
    $("#nextBtn").disabled=false;
    const fl=$("#flip3d");
    fl.addEventListener('click',doFlip);
    fl.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();doFlip();}});
    const bt=$("#blurt"); // typing/clicking in the box must not flip the card
    if(bt){ ['click','mousedown','keydown','keyup'].forEach(ev=>bt.addEventListener(ev,e=>e.stopPropagation())); bt.addEventListener('input',()=>{ if(c) blurtStore[c.id]=bt.value; }); }
  }

  else if(c.type==="gap"){
    const done=state.answered[c.id];
    let idx=0;
    const parts=c.text.split("___").map((seg,k,arr)=>{
      let out=esc(seg);
      if(k<arr.length-1){
        const i=idx++;
        if(done){
          const ok=done.marks[i];
          out+=`<span class="gap-input ${ok?'right':'wrong'}"><span class="sr">Your answer, ${ok?'correct':'incorrect'}: </span><span aria-hidden="true">${ok?'✓ ':'✗ '}</span>${esc(done.vals[i]||'—')}</span>`;
          if(!ok)out+=` <span class="gap-answer"><span class="sr">Correct answer: </span>(${esc((done.show&&done.show[i])||canonical(c.answers[i]))})</span>`;
        } else {
          out+=`<input class="gap-input" data-gi="${i}" aria-label="blank ${i+1}" autocomplete="off" maxlength="300">`;
        }
      }
      return out;
    }).join("");
    host.innerHTML=`<div class="cardbox${back}">${tag}
      <div class="gap-text">${parts}</div>
      ${done?`<div class="muted">${done.allRight?'✓ All correct — well done.':'You got '+done.marks.filter(Boolean).length+' of '+done.marks.length+'. The correct answers are shown in brackets.'}</div>`
        :`<div class="flip-hint" id="gapNote">Type your answers, then check.</div>`}
    </div>`;
    c._blankWarned=false;act.textContent=done?"Next ›":"Check answers";
    act.className="ctl primary";act.disabled=false;
    $("#nextBtn").disabled=false;
    const first=host.querySelector('input');if(first&&!IS_TOUCH)first.focus({preventScroll:true});
    {const _ins=[...host.querySelectorAll('input')];_ins.forEach((inp,ix)=>inp.addEventListener('keydown',e=>{if(e.key!=='Enter'||state.answered[c.id])return;e.preventDefault();if(ix<_ins.length-1)_ins[ix+1].focus();else checkGap(c);}));}
  }

  else if(c.type==="mcq"){
    const done=state.answered[c.id];
    const ord=(done&&done.ord)?done.ord:(c._ord=mcqOrder(c));
    const choices=ord.map((orig,k)=>{
      let cls="choice", pre='';
      if(done){ if(orig===c.correct){cls+=" correct";pre='<span class="mark" aria-hidden="true">✓</span><span class="sr">Correct answer: </span>';} else if(orig===done.pick){cls+=" incorrect";pre='<span class="mark" aria-hidden="true">✗</span><span class="sr">Your answer, incorrect: </span>';} }
      return `<button class="${cls}" data-ci="${k}" type="button" ${done?'disabled':''}>${pre}${esc(c.options[orig])}</button>`;
    }).join("");
    host.innerHTML=`<div class="cardbox${back}">${tag}
      <div class="q">${esc(c.question)}</div>
      <div class="choices">${choices}</div>
      ${done?`<div class="why"><b>${done.pick===c.correct?'✓ Correct.':'✗ Not quite. The correct answer is: '+esc(c.options[c.correct])+'.'}</b> ${esc(whyText(c))}</div>`:''}
    </div>`;
    act.textContent="Next ›";act.className="ctl primary";act.disabled=!done;
    $("#nextBtn").disabled=false;
    if(!done)host.querySelectorAll('.choice').forEach(b=>b.addEventListener('click',()=>pickMcq(c,+b.dataset.ci)));
  }

  else if(c.type==="match"){
    const done=state.answered[c.id];
    // De-duplicate the right-hand values: "sort into categories" cards reuse a label
    // across rows, so each distinct option appears once and can be chosen on several rows.
    const distinct=[...new Set(c.pairs.map(p=>p[1]))];
    const rights=done?done.options:shuffle(distinct);
    if(!done) c._opts=rights;
    const opts=(done?done.options:c._opts);
    const rows=c.pairs.map((p,k)=>{
      const sel=done?done.sel[k]:"";
      let cls="match-sel";
      if(done)cls+= (norm(sel)===norm(p[1]))?" right":" wrong";
      const optionTags=opts.map(o=>`<option value="${esc(o)}" ${o===sel?'selected':''}>${esc(o)}</option>`).join("");
      return `<div class="match-row">
        <div class="match-left">${esc(p[0])}</div>
        <select class="${cls}" data-mi="${k}" aria-label="Match for ${esc(p[0])}" ${done?'disabled':''}>
          <option value="">Choose…</option>${optionTags}
        </select></div>
        ${done?(norm(sel)!==norm(p[1])?`<div class="match-row"><div></div><div class="gap-answer" style="font-size:14px"><span class="res-bad">✗ Incorrect.</span> Correct match: ${esc(p[1])}</div></div>`:`<div class="match-row"><div></div><div class="res-ok">✓ Correct</div></div>`):''}`;
    }).join("");
    host.innerHTML=`<div class="cardbox${back}">${tag}
      <div class="q" style="font-size:18px">${esc(c.prompt)}</div>
      <div class="match-grid">${rows}</div>
      ${done?`<div class="muted">${done.allRight?'✓ All matched correctly.':'You matched '+c.pairs.filter((p,k)=>norm(done.sel[k])===norm(p[1])).length+' of '+c.pairs.length+'. The correct match is shown under each miss.'}</div>`:`<div class="flip-hint" id="matchNote">Pick the match for each, then check.</div>`}
    </div>`;
    c._blankWarned=false;act.textContent=done?"Next ›":"Check matches";act.className="ctl primary";act.disabled=false;
    $("#nextBtn").disabled=false;
  }
}

/* Record a graded answer: update score + streak, then re-render in place (no slide). */
function scoreAnswer_old(correct){
  state.answeredCount++;
  if(correct){ state.score++; state.streak++; }
  else { state.streak=0; }
  state.dir=0;
  render();
}
function pickMcq_old(c,pick){
  state.answered[c.id]={pick};
  scoreAnswer(pick===c.correct);
}
function checkGap_old(c){
  const host=$("#cardHost");
  const vals=[],marks=[];let all=true;
  c.answers.forEach((ans,i)=>{
    const inp=host.querySelector(`input[data-gi="${i}"]`);
    const v=inp?inp.value:"";vals.push(v);
    const ok=accepts(ans,v);marks.push(ok);if(!ok)all=false;
  });
  state.answered[c.id]={vals,marks,allRight:all};
  scoreAnswer(all);
}
function checkMatch_old(c){
  const host=$("#cardHost");
  const sel=[];let all=true;
  c.pairs.forEach((p,k)=>{
    const s=host.querySelector(`select[data-mi="${k}"]`);
    const v=s?s.value:"";sel.push(v);
    if(norm(v)!==norm(p[1]))all=false;
  });
  state.answered[c.id]={sel,options:c._opts,allRight:all};
  scoreAnswer(all);
}
/* Show/refresh the streak pill. Pops when the number goes up. */
let lastStreakShown=0;
function updateStreak(){
  const pill=$("#streakPill"), num=$("#streakNum");
  if(state.streak>=2){
    pill.hidden=false; num.textContent=state.streak;
    if(state.streak>lastStreakShown){ pill.classList.remove('pop'); void pill.offsetWidth; pill.classList.add('pop'); }
  } else {
    pill.hidden=true;
  }
  lastStreakShown=state.streak;
}

/* ===== Finish ===== */
function recordBestScore(pct){
  // Record best % per topic (for topic sessions only; custom sessions span topics).
  if(!state.topic)return;
  const m=mastery[state.topic]=mastery[state.topic]||{best:0};
  if(pct>m.best){ m.best=pct; saveMastery(); }
}
function finish(){
  stopSpeaking(); try{ const _k=sessKey(state.topic); if(state.topic&&sessions[_k]) sessions[_k].finished=true; }catch(e){}
  $("#progFill").style.width="100%";
  const graded=state.answeredCount;
  const label = state.custom ? (state.custom.quick?`your Quick 15`:state.custom.search?`your search results`:`your custom session`) : (currentTopics().find(x=>x.key===state.topic)||{}).title;
  if(graded>0){
    const pct=Math.round(state.score/graded*100);
    if(graded*2>=state.deck.length) recordBestScore(pct);
    $("#doneTitle").textContent= pct>=80?"Strong work":pct>=50?"Good progress":"Keep going";
    $("#doneMsg").textContent=`You scored ${pct}% on the graded questions in ${label}. Flip cards count when you rate them "Got it" or "Not yet". Shuffle and go again to lock them in.`;
    countUp($("#doneScore"), state.score, graded);
    if(graded*2<state.deck.length){ $("#doneMsg").textContent+=` You answered ${graded} of ${state.deck.length} cards, so this was not saved as your best score.`; }
  } else {
    $("#doneScore").textContent="✓";
    $("#doneTitle").textContent="Deck complete";
    $("#doneMsg").textContent=`You've been through every card in ${label}. Shuffle and go again to test your recall.`;
  }
  setDoneLabels(); show("screen-done");
}

/* ===== Mark for review (star) ===== */
function updateCardTools(c){
  const star=$("#starBtn");
  const on=marked.has(c.id);
  star.setAttribute('aria-pressed', on);
  star.textContent = on ? '★' : '☆';
}
$("#starBtn").addEventListener('click',()=>{
  const c=current(); if(!c)return;
  if(marked.has(c.id))marked.delete(c.id); else marked.add(c.id);
  saveMarked();
  updateCardTools(c);
});

/* ===== Read aloud (Web Speech API) ===== */
let speaking=false;
function speechTextFor(c){
  if(c.type==='flip') return state.revealed ? ('Answer. '+c.back) : c.front;
  if(c.type==='gap') return c.text.replace(/___/g,' blank ');
  if(c.type==='mcq'){ const base=c.question+'. Options: '+c.options.join('. '); return state.answered[c.id]? (base+'. '+c.why) : base; }
  if(c.type==='match') return c.prompt+'. '+c.pairs.map(p=>p[0]).join('. ');
  return '';
}
function stopSpeaking(){
  try{ if(window.speechSynthesis){ window.speechSynthesis.cancel(); } }catch(e){}
  speaking=false; const b=$("#speakBtn"); if(b)b.classList.remove('speaking');
}
function speakCard(){
  const synth=window.speechSynthesis;
  if(!synth){ return; } // not supported — button simply does nothing
  if(speaking){ stopSpeaking(); return; }
  const c=current(); if(!c)return;
  const u=new SpeechSynthesisUtterance(speechTextFor(c));
  u.rate=0.98; u.lang='en-GB';
  u.onend=()=>{ speaking=false; $("#speakBtn").classList.remove('speaking'); };
  u.onerror=()=>{ speaking=false; $("#speakBtn").classList.remove('speaking'); };
  try{ synth.cancel(); synth.speak(u); speaking=true; $("#speakBtn").classList.add('speaking'); }catch(e){ speaking=false; }
}
$("#speakBtn").addEventListener('click',speakCard);
// hide the speaker button entirely if speech isn't available
if(!('speechSynthesis' in window)){ const sb=$("#speakBtn"); if(sb)sb.style.display='none'; }

/* ===== Keyboard shortcuts (study screen only) ===== */
document.addEventListener('keydown',e=>{
  if(e.ctrlKey||e.metaKey||e.altKey) return;
  if($("#screen-study").hidden) return;
  const tag=(e.target&&e.target.tagName)||'';
  const typing = tag==='INPUT'||tag==='SELECT'||tag==='TEXTAREA';
  const c=current(); if(!c)return;
  // Enter in a gap input checks answers; let that through, don't hijack.
  if(typing){
    if(e.key==='Enter') return; // handled by the input's own listener
    return; // don't steal typing keys
  }
  if(e.key===' '||e.key==='Enter'){
    const ae=document.activeElement;
    if(ae&&ae.matches&&ae.matches('button,[role="button"],a[href],select')) return; // let the focused control handle Enter/Space itself
    e.preventDefault(); $("#actionBtn").click();
  }
  else if(e.key==='ArrowRight'){ e.preventDefault(); if(!$("#nextBtn").disabled)nextCard(); }
  else if(e.key==='ArrowLeft'){ e.preventDefault(); if(!$("#prevBtn").disabled){state.i--;state.revealed=false;state.dir=-1;render();} }
  else if((e.key==='m'||e.key==='M')){ e.preventDefault(); $("#starBtn").click(); }
  else if((e.key==='r'||e.key==='R')){ e.preventDefault(); $("#speakBtn").click(); }
  else if(c.type==='mcq' && !state.answered[c.id] && /^[1-4]$/.test(e.key)){
    const idx=parseInt(e.key,10)-1;
    const btns=$("#cardHost").querySelectorAll('.choice');
    if(btns[idx]){ e.preventDefault(); btns[idx].click(); }
  }
});
/* Animate the score counting up from 0 to the final value. */
function countUp(el, target, total){
  const reduce = matchMedia('(prefers-reduced-motion:reduce)').matches;
  if(reduce || target===0){ el.textContent=`${target} / ${total}`; return; }
  let n=0; const steps=Math.min(target,20), step=Math.max(1,Math.round(target/steps));
  el.textContent=`0 / ${total}`;
  const iv=setInterval(()=>{
    n=Math.min(target,n+step); el.textContent=`${n} / ${total}`;
    if(n>=target) clearInterval(iv);
  },45);
}

/* ===== Move progress between devices (copy/paste code) ===== */
(function(){
  const SYNC_KEYS=['g2m-marked','g2m-mastery','g2m-seen','g2m-setup','g2m-mode','g2m-theme','g2m-usercards','g2m-opened','g2m-exams-biology','g2m-srs-biology'];window.__G2M_SYNC_KEYS=SYNC_KEYS;
  const btn=$("#syncBtn"),panel=$("#syncPanel"),ta=$("#syncCode"),msg=$("#syncMsg");
  if(!btn)return;
  function flash(text,bad){ msg.textContent=text; msg.classList.toggle('bad',!!bad); msg.hidden=false; }
  function makeCode(){
    const o={};
    SYNC_KEYS.forEach(k=>{try{const v=__LS.getItem(k); if(v!=null)o[k]=v;}catch(e){}});
    o['g2m-ns']='2'; /* marks a code made by the per-subject-key version */
    return 'G2M1:'+btoa(unescape(encodeURIComponent(JSON.stringify(o))));
  }
  btn.addEventListener('click',()=>{ const open=panel.hidden; panel.hidden=!open; if(open)msg.hidden=true; });
  $("#syncClose").addEventListener('click',()=>{ panel.hidden=true; });
  $("#syncCopy").addEventListener('click',async()=>{
    let code; try{code=makeCode();}catch(e){flash('Could not read your progress on this device.',true);return;}
    ta.value=code; ta.focus(); ta.select();
    try{ await navigator.clipboard.writeText(code); flash('Copied! Paste this code on your other device, then tap Load code.'); }
    catch(e){ try{document.execCommand('copy');}catch(_){} flash('Here is your code — select it all and copy, then paste it on your other device.'); }
  });
  $("#syncLoad").addEventListener('click',()=>{
    const code=(ta.value||'').trim();
    if(!code){ flash('Paste a progress code into the box first.',true); return; }
    if(code.length>1500000){ flash('That code is too large to be a progress code.',true); return; }
    if(code.indexOf('G2M1:')!==0){ flash('That does not look like a progress code.',true); return; }
    let o; try{ o=JSON.parse(decodeURIComponent(escape(atob(code.slice(5))))); }catch(e){ flash('That code could not be read — check you copied all of it.',true); return; }
    if(!o || typeof o!=='object' || Array.isArray(o)){ flash('No progress was found in that code.',true); return; }
    const _pick={}; SYNC_KEYS.forEach(k=>{ if(typeof o[k]==='string')_pick[k]=o[k]; });
    if(!Object.keys(_pick).length){ flash('No progress was found in that code.',true); return; }
    const _res=window.__g2mImport?window.__g2mImport(_pick,o['g2m-ns']==='2'):{err:'Loading codes is not available.'};
    if(_res.err){ flash(_res.err,true); return; }
    flash('Progress loaded — refreshing…');
    setTimeout(()=>{ try{location.reload();}catch(e){} },700);
  });
})();

/* ===== physics engine patch (JS) ===== */
const IS_TOUCH=(function(){try{return matchMedia('(pointer:coarse)').matches||(('ontouchstart' in window)&&!matchMedia('(hover:hover)').matches);}catch(e){return false;}})();
const COMBINED_TITLES={};
function topicTitle(t){ return (state.course==='combined'&&COMBINED_TITLES[t.key])||t.title; }
function announce(msg){ const l=document.getElementById('live'); if(!l)return; l.textContent=''; setTimeout(()=>{l.textContent=msg;},40); }

/* answer text: one block per line so numbered steps breathe */
function fmtAns(t){
  return String(t).split('\n').map(l=>{ if(!l.trim()) return ''; const li=/^\s*(?:\d+[.)]|[-•*])\s/.test(l); return '<span class="ln'+(li?' li':'')+'">'+esc(l)+'</span>'; }).join('');
}

/* mcq: per-view option shuffle (indices into c.options); keep "none/both/all of ..." last */
function mcqOrder(c){
  const idx=c.options.map((_,i)=>i);
  const fixed=idx.filter(i=>/^(none|both|all) of\b|^(none|neither)\b/i.test(c.options[i]));
  const free=shuffle(idx.filter(i=>!fixed.includes(i)));
  return free.concat(fixed);
}
/* feedback text must not lean on option letters: quote the option instead */
function whyText(c){
  let w=String(c.why||'');
  const L='ABCD';
  w=w.replace(/\b(?:Option|Answer|Choice)s?\s+([A-D])\b/g,(m,a)=>c.options[L.indexOf(a)]?'“'+c.options[L.indexOf(a)]+'”':m);
  w=w.replace(/(^|[.;:]\s+)([A-D])(?= (?:is|are|describes|shows|says)\b)/g,(m,p,a)=>(c.options[L.indexOf(a)]&&!new RegExp('\\b'+a+'\\b').test(c.question||''))?p+'“'+c.options[L.indexOf(a)]+'”':m);
  return w;
}
function pickMcq(c,pick){
  const ord=c._ord||c.options.map((_,i)=>i);
  const orig=ord[pick];
  state.answered[c.id]={pick:orig,ord:ord.slice()};
  scoreAnswer(orig===c.correct, orig===c.correct?'Correct.':'Not quite. The correct answer is: '+c.options[c.correct]+'.');
}
function scoreAnswer(correct,msg){
  state.answeredCount++;
  if(correct){ state.score++; state.streak++; } else { state.streak=0; }
  state.dir=0;
  render();
  if(msg) announce(msg);
}

/* gap grading: no blank graded, symmetric blanks interchangeable, one answer never fills two blanks */
function gapNote(msg){ const n=document.getElementById('gapNote')||document.getElementById('matchNote'); if(n){ n.textContent=msg; n.setAttribute('role','alert'); } announce(msg); }
function checkGap(c){
  const host=$("#cardHost"); const n=c.answers.length;
  const vals=[]; for(let i=0;i<n;i++){ const inp=host.querySelector('input[data-gi="'+i+'"]'); vals.push(inp?inp.value:''); }
  if(vals.every(v=>!v.trim())&&!c._blankWarned){
    c._blankWarned=true; $("#actionBtn").textContent='Reveal answer';
    gapNote('Type an answer first, or press Reveal answer to see it.');
    const f=host.querySelector('input'); if(f&&!IS_TOUCH) f.focus({preventScroll:true});
    return;
  }
  c._blankWarned=false;
  const L=c.answers.map(a=>Array.isArray(a)?a:[a]); const NL=L.map(l=>l.map(norm)); const segs=c.text.split('___');
  const M=L.map((l,i)=>vals.map(v=>v.trim()?accepts(l,v):false));
  const interch=(i,j)=>{ if(i===j) return true; const lo=Math.min(i,j), hi=Math.max(i,j);
    if(hi===lo+1&&/^\s*(?:,|;|\/|&|and|or|,\s*and|and\s*\/\s*or)\s*$/i.test(segs[hi])) return true;
    return NL[i].some(x=>NL[j].includes(x)); };
  const sameSet=(a,b)=>a.length===b.length&&a.every(x=>b.includes(x));
  // one answer must never fill two blanks: slots holding the same set of alternatives in a different order (clockwise / anticlockwise) cannot both take the same typed value
  const dupClash=(i,j)=>{ for(let m=0;m<j;m++){ const k=slotFor[m]; if(k>=0&&k!==i&&sameSet(NL[i],NL[k])&&NL[i][0]!==NL[k][0]&&norm(vals[m])===norm(vals[j])) return true; } return false; };
  let best=null; const slotFor=new Array(n).fill(-1), used=new Array(n).fill(false);
  (function go(j,cnt,ident){
    if(j===n){ const sc=cnt*100+ident; if(!best||sc>best.sc) best={sc:sc,slotFor:slotFor.slice()}; return; }
    const order=[j].concat(Array.from({length:n},(_,k)=>k).filter(k=>k!==j));
    for(const i of order){ if(!used[i]&&M[i][j]&&interch(i,j)&&!dupClash(i,j)){ used[i]=true; slotFor[j]=i; go(j+1,cnt+1,ident+(i===j?1:0)); used[i]=false; slotFor[j]=-1; } }
    go(j+1,cnt,ident);
  })(0,0,0);
  const marks=best.slotFor.map(x=>x>=0); const allRight=marks.every(Boolean);
  const usedSlots=new Set(best.slotFor.filter(x=>x>=0)); const free=[]; for(let k=0;k<n;k++) if(!usedSlots.has(k)) free.push(k);
  const taken=vals.filter((v,m)=>marks[m]).map(norm); const show=[];
  for(let j=0;j<n;j++){ if(marks[j]){ show.push(null); continue; } const k=free.includes(j)?j:free[0]; const idx=free.indexOf(k); if(idx>=0) free.splice(idx,1); const lst=L[k!==undefined?k:j]; show.push(lst.find(a=>!taken.includes(norm(a)))||lst[0]); }
  state.answered[c.id]={vals:vals,marks:marks,allRight:allRight,show:show};
  const got=marks.filter(Boolean).length;
  scoreAnswer(allRight, allRight?'All correct.':'You got '+got+' of '+n+'. '+show.filter(Boolean).map(x=>'Correct answer: '+x).join('. '));
}
function checkMatch(c){
  const host=$("#cardHost"); const sel=[]; let all=true, any=false;
  c.pairs.forEach((p,k)=>{ const s=host.querySelector('select[data-mi="'+k+'"]'); const v=s?s.value:""; sel.push(v); if(v) any=true; if(norm(v)!==norm(p[1])) all=false; });
  if(!any&&!c._blankWarned){ c._blankWarned=true; $("#actionBtn").textContent='Reveal answers'; gapNote('Choose at least one match first, or press Reveal answers to see them.'); return; }
  c._blankWarned=false;
  state.answered[c.id]={sel:sel,options:c._opts,allRight:all};
  const got=c.pairs.filter((p,k)=>norm(sel[k])===norm(p[1])).length;
  scoreAnswer(all, all?'All matched correctly.':'You matched '+got+' of '+c.pairs.length+'.');
}

/* flip cards: self-rating wired into score / streak / mastery / star */
function rateFlip(c,got){
  const prev=state.answered[c.id];
  if(prev&&prev.flip){ if(prev.got!==got){ state.score+=got?1:-1; state.streak=got?state.streak+1:0; } }
  else { state.answeredCount++; if(got){ state.score++; state.streak++; } else { state.streak=0; } }
  state.answered[c.id]={flip:true,got:got};
  if(!got){ marked.add(c.id); saveMarked(); }
  updateCardTools(c); updateStreak(); saveSession(); syncRate();
  announce(got?'Marked as got it.':'Marked as not yet. Card starred for review.');
  nextCard();
}
function syncFaces(){
  const fl=document.getElementById('flip3d'); if(!fl) return;
  const fr=fl.querySelector('.flip-face.front'), bk=fl.querySelector('.flip-face.is-back'); const rv=state.revealed;
  [[fr,rv],[bk,!rv]].forEach(([el,hide])=>{ if(!el) return; if(hide){ el.setAttribute('aria-hidden','true'); el.setAttribute('inert',''); } else { el.removeAttribute('aria-hidden'); el.removeAttribute('inert'); } });
  const bt=document.getElementById('blurt'); if(bt) bt.tabIndex=rv?-1:0;
}
function syncRate(){
  const row=document.getElementById('rateRow'); if(!row) return; const c=current();
  const on=!!(c&&c.type==='flip'&&state.revealed); row.hidden=!on; if(!on) return;
  const a=state.answered[c.id]; const g=a&&a.flip?a.got:null;
  document.getElementById('rateYes').setAttribute('aria-pressed',String(g===true));
  document.getElementById('rateNo').setAttribute('aria-pressed',String(g===false));
}
function doFlip(){ doFlip_old(); syncFaces(); syncRate(); if(state.revealed){ try{ const _ry=document.getElementById('rateYes'); if(_ry&&!_ry.closest('[hidden]'))_ry.focus({preventScroll:true}); }catch(e){} } announce(state.revealed?'Answer shown. Rate yourself: Got it or Not yet.':'Question shown.'); }
function render(){
  render0(); syncFaces(); syncRate();
  const a=document.getElementById('actionBtn');
  if(state.dir===0&&a&&!a.disabled){ try{ a.focus({preventScroll:true}); }catch(e){} }
  { const ae=document.activeElement; if(!ae||ae===document.body||ae.disabled||!ae.getClientRects().length){ try{ document.getElementById('cardHost').focus({preventScroll:true}); }catch(e){} } }
}
