  function fixLabels(){
    const root=document.getElementById('screen-addcard'); if(!root) return;
    root.querySelectorAll('label.ac-lbl').forEach(l=>{ if(l.htmlFor) return; const nx=l.nextElementSibling; if(nx&&/^(TEXTAREA|INPUT|SELECT)$/.test(nx.tagName)){ if(!nx.id) nx.id='acf'+Math.random().toString(36).slice(2,7); l.htmlFor=nx.id; } });
    root.querySelectorAll('input.ac-input,textarea.ac-input').forEach(e=>{ if(!e.getAttribute('aria-label')&&!document.querySelector('label[for="'+e.id+'"]')) e.setAttribute('aria-label',e.getAttribute('placeholder')||'Card text'); });
  }
